from datetime import datetime
import pytz
import numpy as np

def task_func(time_strings, timezone):
    if len(time_strings) < 2:
        return 0.0

    tz = pytz.timezone(timezone)
    converted = []
    for ts in time_strings:
        dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
        converted.append(tz.localize(dt))

    differences = []
    for i in range(len(converted) - 1):
        differences.append(abs((converted[i + 1] - converted[i]).total_seconds()))

    if not differences:
        return 0.0

    return float(np.mean(differences))

