from sklearn.feature_extraction.text import CountVectorizer
import matplotlib.pyplot as plt

# Constants
STOP_WORDS = ["a", "an", "the", "in", "on", "at", "and", "or"]

def task_func(file_path, save_path=None):
    try:
        df = pd.read_csv(file_path)
    except FileNotFounError:
        raise
    except Exception as e:
        print(e)
        return None

    try:
        if "Text" in df.columns:
            texts = df["Text"]
        else:
            df = pd.read_csv(file_path, header=None)
            texts = df.iloc[:, 0]

        vectorizer = CountVectorizer(stop_words=STOP_WORDS)
        counts = vectorizer.fit_transform(texts).sum(axis=0)
        if hasattr(counts, "A1"):
            counts = counts.A1
        else:
            counts = counts.ravel()

        frequencies = pd.Series(counts, index=vectorizer.get_feature_names_out())
        top_words = frequencies.nlargest(10)

        ax = top_words.plot(kind="bar")

        if save_path is not None:
            plt.savefig(save_path)
            return None

        return ax
    except Exception as e:
        print(e)
        return None

