    month_to_num.update({'sept': 9, 'sep': 9})

    date_series = None
    if date_col is not None:
        date_series = pd.to_datetime(df[date_col], errors='coerce')
    elif isinstance(df.index, pd.DatetimeIndex):
        date_series = df.index.to_series()
    elif isinstance(df.index, pd.PeriodIndex):
        date_series = df.index.to_timestamp().to_series()

    if date_series is None and month_col is not None:
        vals = df[month_col]
        if pd.api.types.is_datetime64_any_dtype(vals):
            date_series = pd.to_datetime(vals, errors='coerce')
        elif not pd.api.types.is_numeric_dtype(vals):
            sample = vals.dropna().astype(str)
            if sample.str.contains(r'\d{4}', regex=True).any():
                date_series = pd.to_datetime(vals, errors='coerce')

    year_series = None
    if date_series is not None:
        year_series = date_series.dt.year
    elif year_col is not None:
        if pd.api.types.is_datetime64_any_dtype(df[year_col]):
            year_series = pd.to_datetime(df[year_col], errors='coerce').dt.year
        else:
            year_series = pd.to_numeric(df[year_col], errors='coerce')
            if year_series.notna().sum() == 0:
                year_series = pd.to_datetime(df[year_col], errors='coerce').dt.year

    month_num = None
    if date_series is not None:
        month_num = date_series.dt.month
    elif month_col is not None:
        vals = df[month_col]
        num = pd.to_numeric(vals, errors='coerce')
        if num.notna().any():
            month_num = num
        else:
            lower_vals = vals.astype(str).str.strip().str.lower().str.rstrip('.')
            month_num = lower_vals.map(month_to_num).astype(float)
    elif isinstance(df.index, pd.DatetimeIndex):
        month_num = pd.Series(df.index.month, index=df.index)
    elif isinstance(df.index, pd.PeriodIndex):
        month_num = pd.Series(df.index.month, index=df.index)
    else:
        idx = df.index.to_series()
        num = pd.to_numeric(idx, errors='coerce')
        if num.notna().any():
            if num.min() == 0 and num.max() == len(df) - 1:
                month_num = pd.Series(range(1, len(df) + 1), index=df.index)
            else:
                month_num = num
        else:
            lower_vals = idx.astype(str).str.strip().str.lower().str.rstrip('.')
            month_num = lower_vals.map(month_to_num).astype(float)

    target_year = datetime.now().year
    if year_series is not None:
        years = pd.to_numeric(year_series, errors='coerce').dropna()
        if not years.empty:
            target_year = int(years.iloc[0])
            mask = pd.to_numeric(year_series, errors='coerce') == target_year
            if mask.any():
                df = df.loc[mask]
                y = y.loc[mask]
                if month_num is not None:
                    month_num = month_num.loc[mask]

    if month_num is None:
        month_num = pd.Series(range(1, len(df) + 1), index=df.index)
    elif month_num.notna().sum() == 0:
        month_num = pd.Series(range(1, len(df) + 1), index=df.index)

    fig, ax = plt.subplots()
    ax.set_title(f'Monthly Data for {target_year}')
    ax.set_xlabel('Month')
    ax.set_ylabel('Value')

    plot_df = pd.DataFrame({
        'month_num': pd.to_numeric(month_num, errors='coerce'),
        'value': pd.to_numeric(y, errors='coerce')
    }).dropna(subset=['month_num', 'value'])

    if plot_df.empty:
        return ax

    plot_df['month_num'] = plot_df['month_num'].astype(int)
    plot_df = plot_df[(plot_df['month_num'] >= 1) & (plot_df['month_num'] <= 12)]

    if plot_df.empty:
        return ax

    plot_df = plot_df.sort_values('month_num')
    months_present = sorted(plot_df['month_num'].unique())

    ax.bar(plot_df['month_num'], plot_df['value'])
    ax.set_xticks(months_present)
    ax.set_xticklabels([datetime(2000, int(m), 1).strftime('%b') for m in months_present])

    return ax
